  return { value: fallback || '', source: fallback ? 'default' : 'missing', blocked: blocked };
}
function safeEqual(a, b) {
  if (!a || a.length !== b.length) return false;
  var diff = 0;
  for (var i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

var item = $input.first().json || {};
var headers = item.headers || {};
var body = item.body || item;
var secretCfg = readCfg('N8N_WEBHOOK_SECRET', '');
var sheetCfg = readCfg('GOOGLE_SHEET_ID', '19kurWKXLoijsf29tKzedhRHbbg7g9qiSZkcjUszHRhs');
var expected = secretCfg.value;
var provided = String(headers['x-dashboard-secret'] || headers['X-Dashboard-Secret'] || '');
var action = String(body.action || '').trim().toUpperCase();

var error = '';
var httpStatus = 200;
if (secretCfg.blocked && !expected) {
  error = 'n8n $env/secret access denied; configure N8N_BLOCK_ENV_ACCESS_IN_NODE=false or $vars.';
  httpStatus = 500;
} else if (!expected || !safeEqual(provided, expected)) {
  error = 'Unauthorized webhook secret.';
  httpStatus = 403;
} else if (['CHECK_CONNECTIONS', 'VERIFY_PUBLICATION', 'SAFE_RETRY'].indexOf(action) === -1) {
  error = 'Invalid recovery action: ' + action;
  httpStatus = 400;
}

return [{
  json: {
    valid: !error,
    error: error,
    httpStatus: httpStatus,
    action: action,
    sheet_id: sheetCfg.value,
    post_uuid: String(body.post_uuid || ''),
    post_id: String(body.post_id || ''),
    container_id: String(body.container_id || ''),
    execution_id: String(body.execution_id || ''),
    ig_user_id: String(body.ig_user_id || readCfg('INSTAGRAM_USER_ID', '17841453414532595').value),
    resolution: action === 'SAFE_RETRY' ? 'RESET_DRAFT' : String(body.resolution || 'CHECK_EXECUTION').toUpperCase(),
    published_id: String(body.published_id || ''),
    published_url: String(body.published_url || '')
  }
}];

// Safeguard marker: INSTAOPS_V2_RECOVERY — proves Supabase RPC+RLS+schema via instaops_verify_health_and_rpc, handles empty Google Sheets gracefully, and surfaces n8nEnv diagnostics.
return (async function () {
  var self = this;
  function readCfg(key, fallback) {
    var blocked = false;
    try { if (typeof $env !== 'undefined' && $env && $env[key] !== undefined && $env[key] !== null && $env[key] !== '') return { value: String($env[key]), source: 'env', blocked: false }; } catch (_) { blocked = true; }
    try { if (typeof $vars !== 'undefined' && $vars && $vars[key] !== undefined && $vars[key] !== null && $vars[key] !== '') return { value: String($vars[key]), source: 'vars', blocked: blocked }; } catch (_) {}
    return { value: fallback || '', source: fallback ? 'default' : 'missing', blocked: blocked };
  }
  async function httpCall(opts) {
    if (self && self.helpers && typeof self.helpers.httpRequest === 'function') return await self.helpers.httpRequest(opts);
    if (typeof fetch === 'function') {
      var headers = Object.assign({}, opts.headers || {});
      var body = opts.body !== undefined ? (typeof opts.body === 'string' ? opts.body : JSON.stringify(opts.body)) : undefined;
      if (body && !headers['Content-Type']) headers['Content-Type'] = 'application/json';
      var res = await fetch(opts.url, { method: opts.method || 'GET', headers: headers, body: body });
      var text = await res.text();
      var parsed = text;
      try { parsed = text ? JSON.parse(text) : {}; } catch (_) {}
      return { statusCode: res.status, body: parsed, headers: {} };
    }
    throw new Error('No HTTP helper available.');
  }

  var secretCfg = readCfg('N8N_WEBHOOK_SECRET', '');
  var sbUrlCfg = readCfg('SUPABASE_URL', 'https://cdgwdlhesgcxmswsamrj.supabase.co');
  var sbKeyCfg = readCfg('SUPABASE_SERVICE_ROLE_KEY', '');
  var cldNameCfg = readCfg('CLOUDINARY_CLOUD_NAME', 'djkkknb9k');
  var cldKeyCfg = readCfg('CLOUDINARY_API_KEY', '');
  var cldSecretCfg = readCfg('CLOUDINARY_API_SECRET', '');
  var metaTokenCfg = readCfg('META_GRAPH_TOKEN', '');
  var graphVerCfg = readCfg('INSTAGRAM_GRAPH_VERSION', 'v22.0');
  var igUserCfg = readCfg('INSTAGRAM_USER_ID', '17841453414532595');
  var livePubCfg = readCfg('LIVE_PUBLISH_ENABLED', 'false');
  var liveDelCfg = readCfg('LIVE_DELETE_ENABLED', 'false');
  var schedCfg = readCfg('SCHEDULING_ENABLED', 'false');

  var envBlocked = [secretCfg, sbKeyCfg, cldKeyCfg, cldSecretCfg, metaTokenCfg, livePubCfg, liveDelCfg, schedCfg].some(function (c) { return c.blocked && c.source === 'missing'; });
  var n8nEnv = {
    ok: !envBlocked && Boolean(secretCfg.value && sbKeyCfg.value),
    envBlocked: envBlocked,
    livePublishEnabled: livePubCfg.value.toLowerCase() === 'true',
    liveDeleteEnabled: liveDelCfg.value.toLowerCase() === 'true',
    schedulingEnabled: schedCfg.value.toLowerCase() === 'true',
    detail: envBlocked ? '$env access denied in n8n (set N8N_BLOCK_ENV_ACCESS_IN_NODE=false or populate $vars)' : 'n8n secrets and flags readable'
  };

  // Empty worksheet with alwaysOutputData:true produces 0 items or [{}] — both are healthy reachable sheets!
  var sheetItems = $input.all();
  var sheetErr = sheetItems[0] && sheetItems[0].json ? sheetItems[0].json.error : null;
  var nonEmptyRows = sheetItems.filter(function (it) { return it && it.json && (it.json.post_id || it.json.post_uuid); });
  var sheetsDiag = {
    ok: !sheetErr,
    detail: sheetErr ? String(sheetErr.message || sheetErr) : ('Google Sheets reporting reachable (' + nonEmptyRows.length + ' rows)')
  };

  var sbDiag = { ok: false, detail: 'Missing SUPABASE_SERVICE_ROLE_KEY' };
  if (sbKeyCfg.value) {
    try {
      var sbRes = await httpCall({
        method: 'POST',
        url: sbUrlCfg.value.replace(/\/$/, '') + '/rest/v1/rpc/instaops_verify_health_and_rpc',
        headers: { apikey: sbKeyCfg.value, Authorization: 'Bearer ' + sbKeyCfg.value, 'Content-Type': 'application/json' },
        body: {},
        json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 10000
      });
      var sRow = Array.isArray(sbRes.body) ? sbRes.body[0] : sbRes.body;
      var rpcOk = Boolean(sbRes.statusCode < 300 && sRow && sRow.schema_ok === true && sRow.rls_ok === true && sRow.anon_revoked_ok === true && sRow.atomic_rpc_ok === true);
      sbDiag = {
        ok: rpcOk,
        detail: rpcOk ? ('Supabase RPC, RLS & schema verified (' + String(sRow.detail || 'ok') + ')') : ('Supabase RPC diagnostic failed: ' + String((sRow && (sRow.detail || sRow.message)) || ('HTTP ' + sbRes.statusCode)))
      };
    } catch (e) {
      sbDiag = { ok: false, detail: 'Supabase probe failed: ' + (e && e.message ? e.message : 'network error') };
    }
  }

  var cldDiag = { ok: false, detail: 'Missing Cloudinary API credentials in n8n' };
  if (cldKeyCfg.value && cldSecretCfg.value) {
    try {
      var cldAuth = 'Basic ' + Buffer.from(cldKeyCfg.value + ':' + cldSecretCfg.value).toString('base64');
      var cRes = await httpCall({ method: 'GET', url: 'https://api.cloudinary.com/v1_1/' + encodeURIComponent(cldNameCfg.value) + '/usage', headers: { Authorization: cldAuth }, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 10000 });
      var cb = cRes.body || {};
      cldDiag = (cRes.statusCode < 300 && !cb.error)
        ? { ok: true, detail: 'Plan ' + String(cb.plan || 'Active') + ' (' + String(cb.resources !== undefined ? cb.resources : 0) + ' resources)' }
        : { ok: false, detail: String((cb.error && cb.error.message) || ('HTTP ' + cRes.statusCode)) };
    } catch (e) {
      cldDiag = { ok: false, detail: 'Cloudinary probe failed: ' + (e && e.message ? e.message : 'network error') };
    }
  }

  var igDiag = { ok: false, detail: 'Missing META_GRAPH_TOKEN in n8n' };
  if (metaTokenCfg.value) {
    try {
      var iRes = await httpCall({ method: 'GET', url: 'https://graph.facebook.com/' + encodeURIComponent(graphVerCfg.value || 'v22.0') + '/' + encodeURIComponent(igUserCfg.value) + '?fields=id,username', headers: { Authorization: 'Bearer ' + metaTokenCfg.value }, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 10000 });
      var ib = iRes.body || {};
      igDiag = (iRes.statusCode < 300 && !ib.error && ib.id)
        ? { ok: true, detail: 'Verified IG user @' + String(ib.username || ib.id) }
        : { ok: false, detail: String((ib.error && ib.error.message) || ('HTTP ' + iRes.statusCode)) };
    } catch (e) {
      igDiag = { ok: false, detail: 'Instagram Graph probe failed: ' + (e && e.message ? e.message : 'network error') };
    }
  }

  return [{ json: { ok: true, services: { supabase: sbDiag, sheets: sheetsDiag, cloudinary: cldDiag, instagram: igDiag, n8nEnv: n8nEnv } } }];
}).call(this);

// Safeguard marker: INSTAOPS_V2_RECOVERY — refuses client-supplied PUBLISHED claims without live Meta Graph API verification.
return (async function () {
  var self = this;
  function readCfg(key, fallback) {
    var blocked = false;
    try { if (typeof $env !== 'undefined' && $env && $env[key] !== undefined && $env[key] !== null && $env[key] !== '') return { value: String($env[key]), source: 'env', blocked: false }; } catch (_) { blocked = true; }
    try { if (typeof $vars !== 'undefined' && $vars && $vars[key] !== undefined && $vars[key] !== null && $vars[key] !== '') return { value: String($vars[key]), source: 'vars', blocked: blocked }; } catch (_) {}
    return { value: fallback || '', source: fallback ? 'default' : 'missing', blocked: blocked };
  }
  async function httpCall(opts) {
    if (self && self.helpers && typeof self.helpers.httpRequest === 'function') return await self.helpers.httpRequest(opts);
    if (typeof fetch === 'function') {
      var headers = Object.assign({}, opts.headers || {});
      var body = opts.body !== undefined ? (typeof opts.body === 'string' ? opts.body : JSON.stringify(opts.body)) : undefined;
      if (body && !headers['Content-Type']) headers['Content-Type'] = 'application/json';
      var res = await fetch(opts.url, { method: opts.method || 'GET', headers: headers, body: body });
      var text = await res.text();
      var parsed = text;
      try { parsed = text ? JSON.parse(text) : {}; } catch (_) {}
      return { statusCode: res.status, body: parsed, headers: {} };
    }
    throw new Error('No HTTP helper available.');
  }

  var req = $('CODE | Validate Recovery Operation').item.json;
  var sbUrlCfg = readCfg('SUPABASE_URL', 'https://cdgwdlhesgcxmswsamrj.supabase.co');
  var sbKeyCfg = readCfg('SUPABASE_SERVICE_ROLE_KEY', '');
  var metaTokenCfg = readCfg('META_GRAPH_TOKEN', '');
  var graphVer = readCfg('INSTAGRAM_GRAPH_VERSION', 'v22.0').value || 'v22.0';

  if (!sbKeyCfg.value) {
    return [{ json: { ok: false, verified: false, error: sbKeyCfg.blocked ? 'n8n $env/secret access denied; configure N8N_BLOCK_ENV_ACCESS_IN_NODE=false or $vars.' : 'Missing SUPABASE_SERVICE_ROLE_KEY.' } }];
  }
  var sbUrl = sbUrlCfg.value.replace(/\/$/, '');
  var sbHeaders = { apikey: sbKeyCfg.value, Authorization: 'Bearer ' + sbKeyCfg.value, 'Content-Type': 'application/json' };
  var filter = req.post_uuid ? ('id=eq.' + encodeURIComponent(req.post_uuid)) : ('post_id=eq.' + encodeURIComponent(req.post_id));
  var pRes = await httpCall({ method: 'GET', url: sbUrl + '/rest/v1/instaops_posts?' + filter + '&select=*', headers: sbHeaders, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 15000 });
  var row = Array.isArray(pRes.body) ? pRes.body[0] : null;
  if (!row) {
    return [{ json: { ok: false, verified: false, error: 'Post not found for reconciliation.' } }];
  }
  var now = new Date().toISOString();
  var resolution = String(req.resolution || 'CHECK_EXECUTION').toUpperCase();

  if (resolution === 'MARK_PUBLISHED' || resolution === 'CHECK_EXECUTION') {
    if (!metaTokenCfg.value) {
      return [{ json: { ok: false, verified: false, status: row.status || 'VERIFY_MANUALLY', error: metaTokenCfg.blocked ? 'n8n $env access denied for META_GRAPH_TOKEN.' : 'META_GRAPH_TOKEN is required to verify publication against Instagram Graph API.' } }];
    }
    var candidateId = String(req.published_id || row.published_id || '').trim();
    var containerId = String(req.container_id || row.container_id || '').trim();
    var verifiedId = '';
    var verifiedUrl = '';
    var verified = false;

    if (candidateId) {
      var mRes = await httpCall({ method: 'GET', url: 'https://graph.facebook.com/' + encodeURIComponent(graphVer) + '/' + encodeURIComponent(candidateId) + '?fields=id,permalink,media_type,timestamp', headers: { Authorization: 'Bearer ' + metaTokenCfg.value }, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 15000 });
      var mb = mRes.body || {};
      if (mRes.statusCode < 300 && !mb.error && mb.id && String(mb.id) === candidateId) {
        verified = true;
        verifiedId = String(mb.id);
        verifiedUrl = String(mb.permalink || '');
      }
    } else if (containerId) {
      var cRes = await httpCall({ method: 'GET', url: 'https://graph.facebook.com/' + encodeURIComponent(graphVer) + '/' + encodeURIComponent(containerId) + '?fields=id,status_code,status', headers: { Authorization: 'Bearer ' + metaTokenCfg.value }, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 15000 });
      var cb = cRes.body || {};
      if (cRes.statusCode < 300 && !cb.error && String(cb.status_code || '').toUpperCase() === 'PUBLISHED') {
        var feedRes = await httpCall({ method: 'GET', url: 'https://graph.facebook.com/' + encodeURIComponent(graphVer) + '/' + encodeURIComponent(row.ig_user_id || req.ig_user_id) + '/media?fields=id,permalink,caption,timestamp&limit=10', headers: { Authorization: 'Bearer ' + metaTokenCfg.value }, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 15000 });
        var list = feedRes.body && Array.isArray(feedRes.body.data) ? feedRes.body.data : [];
        var targetCaption = String(row.caption || row.original_caption || '').trim();
        var found = list.find(function (m) { return targetCaption ? String(m.caption || '').trim() === targetCaption : true; }) || list[0];
        if (found && found.id) {
          verified = true;
          verifiedId = String(found.id);
          verifiedUrl = String(found.permalink || '');
        }
      }
    }

    if (!verified || !verifiedId) {
      return [{ json: { ok: true, verified: false, post_uuid: row.id, post_id: row.post_id, status: row.status || 'VERIFY_MANUALLY', error: 'Meta Graph API could not verify published media ID or container; refusing unverified MARK_PUBLISHED.' } }];
    }

    await httpCall({ method: 'PATCH', url: sbUrl + '/rest/v1/instaops_posts?id=eq.' + encodeURIComponent(row.id), headers: sbHeaders, body: { status: 'PUBLISHED', published_id: verifiedId, published_url: verifiedUrl || row.published_url || '', published_at: row.published_at || now, error: '', error_code: '', error_stage: '', sheets_sync_status: 'PENDING' }, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true });
    await httpCall({ method: 'DELETE', url: sbUrl + '/rest/v1/instaops_job_locks?lock_key=eq.' + encodeURIComponent('post:' + row.id), headers: sbHeaders, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true });
    return [{ json: { ok: true, verified: true, post_uuid: row.id, post_id: row.post_id, status: 'PUBLISHED', published_id: verifiedId, published_url: verifiedUrl } }];
  }

  if (row.status === 'PUBLISHED' || (row.published_id && String(row.published_id).trim() !== '')) {
    return [{ json: { ok: false, verified: false, error: 'Already PUBLISHED post cannot be reset via recovery.' } }];
  }
  var nextStatus = resolution === 'MARK_FAILED' ? 'FAILED' : (row.media_url ? 'READY' : 'DRAFT');
  var patch = {
    status: nextStatus,
    error: nextStatus === 'READY' || nextStatus === 'DRAFT' ? '' : (row.error || ''),
    error_code: nextStatus === 'READY' || nextStatus === 'DRAFT' ? '' : (row.error_code || ''),
    sheets_sync_status: 'PENDING'
  };
  await httpCall({ method: 'PATCH', url: sbUrl + '/rest/v1/instaops_posts?id=eq.' + encodeURIComponent(row.id), headers: sbHeaders, body: patch, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true });
  if (resolution === 'RELEASE_LOCK' || resolution === 'RESET_DRAFT' || resolution === 'MARK_READY' || resolution === 'MARK_FAILED') {
    await httpCall({ method: 'DELETE', url: sbUrl + '/rest/v1/instaops_job_locks?lock_key=eq.' + encodeURIComponent('post:' + row.id), headers: sbHeaders, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true });
  }
  return [{ json: { ok: true, verified: false, post_uuid: row.id, post_id: row.post_id, status: nextStatus } }];
}).call(this);
